#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;

    #pragma omp parallel
    {
        double local_product = 1.0;

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(x.size()); ++i) {
            local_product *= (i % 2 == 0) ? x[static_cast<std::size_t>(i)]
                                          : (1.0 / x[static_cast<std::size_t>(i)]);
        }

        #pragma omp critical
        {
            product *= local_product;
        }
    }

    return product;
}
